#!/usr/bin/env python3
"""Writes the Slime King's SKILL prompts for ChatGPT/Gemini (2026-11-11): Radiant Ooze (the spit), Royal Decree (the staff points), Staff Raise (Kingdom's Wrath and Absolute Judgment), Crown Slam (the dive) and the Heal.
Built on write_prompts.py (the hit, death and dodge prompts: the same CHARACTER, VIEW, SOFT, RIGID blocks and the same build()), with what the King's first three sheets taught (docs/SLIME_KING.md):
  - the dodge sheet came with TEXT LABELS painted under the panels (the pose names of the brief): the brief now says the pose names are for the generator only and must never be written;
  - the hit sheet drew a clenched fist BESIDE a floating staff in two panels, a staff lying down and cut by the sheet's edge, the panels in another order and a grimace instead of the rest pose in the last: the brief now says
    the glove is closed round the staff in EVERY panel, the staff never lies down or leaves the panel, the panels stay in the listed order and the rest face is the smug half-lidded one;
  - the cell of the strip holds only about 75 px (cell scale) to the right of the King's base, so the staff's reach is kept small (tilts of 12 degrees, lifts instead of swings) and the creature is asked SMALL.

  python Animations/SlimeKing/source/write_skill_prompts.py

Output: Animations/SlimeKing/<folder>/source/<folder>_prompt.txt (the user pastes the text between the two lines of equals signs into ChatGPT with Animations/SlimeKing/reference_image.png attached).
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import write_prompts as wp

ROOT = wp.ROOT

# ---- the blocks, with the new lessons (the module's globals are replaced: build() reads them)
wp.LESSONS = """LESSONS FROM THE EARLIER SHEETS (docs/SLIME_KING.md): (1) The King's idle sheet came out excellent from ChatGPT, which kept the size, the floor and the spacing: ask for a SMALL creature with lots of empty space and a margin round every part that sticks out (the crown tips, the staff tip, the glove). (2) THE GENERATOR EXAGGERATES BODY MOTION two to three times: the numbers below are small on purpose. (3) THE GLOVE ALWAYS HOLDS THE STAFF: in EVERY panel the glove is closed round the staff's shaft with the same grip as the reference, and glove and staff move together as one rigid piece; never a clenched fist beside a staff, never an open hand, never a staff floating alone, never a staff lying down or reaching the panel's edge. (4) THE PANELS STAY IN THE ORDER LISTED, the rest pose appears only where the list says so, and the rest pose has the King's calm half-lidded eyes and gentle closed smile (an earlier sheet drew a grimace in the rest panels: wrong). (5) NO WORDS ANYWHERE: the pose names in this brief are for you only; an earlier sheet came back with labels (REST POSE, APEX...) written under the panels: wrong. (6) The face may change from panel to panel as described, but it is always the King's own face."""

wp.BACKGROUND = """BACKGROUND AND LAYOUT: one flat pure MAGENTA (#FF00FF) background filling the whole image, identical in every pixel. No gradient, floor, ground line, shadow, glow or vignette. NO GRID LINES, NO BORDERS and no lines between or around the panels. NO TEXT OF ANY KIND: the pose names and the numbers in this brief are instructions for you only, so do not write them, or any word, letter, number or caption, anywhere in the image, not under a panel, not in a corner. No pink, magenta or purple on the creature itself (the inside of an open mouth is dark warm brown); its outline is dark warm brown and hard-edged."""

wp.REPLIES = wp.REPLIES.replace('If it draws more or fewer panels than asked:',
    'If it writes any text, label, caption or number: "Redo it. NO TEXT anywhere in the image: no pose names, no labels, no numbers, no captions under or over the panels; only the creature on flat magenta." '
    'If the glove is a loose fist or an open hand beside the staff, or the staff floats alone, lies down or reaches the panel edge: "Redo it. In EVERY panel the glove is closed round the staff\'s shaft with the same grip as the reference image; glove and staff are ONE rigid piece that moves together; the staff never lies down and stays well inside the panel." '
    'If the panels are in a different order or a rest panel has a grimace: "Redo it. The panels are in EXACTLY the order listed; panel 1 is exactly the rest pose of the reference (half-lidded smug eyes, a gentle closed smile)." '
    'If it draws more or fewer panels than asked:')


def SCALE(n, pct, floor_note):
    return ("SAME SCALE AND FLOOR (very important): draw the creature at the same size in all %s panels: the bottom row must NOT be drawn bigger than the top row, and the creature is SMALL: in panel 1 the BASE of the King, its flat underside, is only about %d%% of the panel width and its lowest point is about 88%% down the panel (the floor line, the same in every panel), with lots of empty magenta all round. %s The base rests on the floor line in every panel (unless said otherwise below), does not slide left or right and keeps its width (within 3%%). The King's middle stays over the same spot in every panel. EVERY part, the crown tips, the raised or tilted staff and the glove included, stays at least 10%% of the panel away from every panel edge, above all the RIGHT edge (an earlier sheet let the staff run out of the panel): if a pose would bring the staff nearer than that, draw the whole creature smaller in ALL panels instead. Do not zoom in or out between panels." % (n, pct, floor_note))


ANIMS = []

